import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Flows","description":"","frontmatter":{"title":"Flows"},"headers":[],"relativePath":"language-reference/flows.md","filePath":"language-reference/flows.md"}'),o={name:"language-reference/flows.md"};function l(i,e,p,c,r,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to &quot;Flows&quot;">​</a></h1><p>Flows are rates of change to the stocks in the model. In our REPL model we are looking at two behaviors: how the orchestrator spins up and shuts down instances and how the cache manages its resources (memory and storage).</p><p>When writing a spec you first need to decide either what behavior you want to understand the mechanics of or what behavior you want to prove is impossible. With the orchestrator we want to assert that containers get stood up correctly. Our stocks are a pool of active instances and a pool of loaded images. So we&#39;ll define our flows based on how we think those pools will change given the state of the orchestrator.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def control = flow{</span></span>
<span class="line"><span>    p: new pool,</span></span>
<span class="line"><span>    add: func{</span></span>
<span class="line"><span>        if p.loading &gt; 0{</span></span>
<span class="line"><span>            p.loading -&gt; 1;</span></span>
<span class="line"><span>            p.instances &lt;- 1;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    remove: func{</span></span>
<span class="line"><span>        p.instances -&gt; 1;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    boot: func{</span></span>
<span class="line"><span>        p.loading &lt;- 1;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>First we initialize a copy of our defined stock <code>p: new pool</code>. Since Fault functions do not take arguments we can only access values that either are part of the flow or are defined as constants.</p><p>This means we tend to group functions that change the them stock together in the same flow object.</p><h2 id="changing-the-stock-value" tabindex="-1">Changing the Stock Value <a class="header-anchor" href="#changing-the-stock-value" aria-label="Permalink to &quot;Changing the Stock Value&quot;">​</a></h2><p>Flow functions don&#39;t return values. They are <em>designed</em> for side effects, which will certainly annoy some but reflects how systems typically behave. The same activity might affect multiple things at once.</p><p>Instead flow&#39;s change stock by sending them values.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Operator</th><th style="text-align:left;">Example</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>=</code></td><td style="text-align:left;"><code>example.stock = 10;</code></td><td style="text-align:left;">Resets the value of the stock to some other value.</td></tr><tr><td style="text-align:left;"><code>-&gt;</code></td><td style="text-align:left;"><code>example.stock -&gt; 10;</code></td><td style="text-align:left;">Decrements the stock by the right side value</td></tr><tr><td style="text-align:left;"><code>&lt;-</code></td><td style="text-align:left;"><code>example.stock &lt;- 10;</code></td><td style="text-align:left;">Increments the stock by the right side value</td></tr></tbody></table><h2 id="swapping-the-initial-stock-for-another" tabindex="-1">Swapping the initial stock for another <a class="header-anchor" href="#swapping-the-initial-stock-for-another" aria-label="Permalink to &quot;Swapping the initial stock for another&quot;">​</a></h2><p>When you initialize a flow in the run block or the state chart it will automatically create unique instances of the stocks attached to it, but you can swap these out for other instances of the same stock immediately after initialization.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init {</span></span>
<span class="line"><span>    pool2  = new pool;</span></span>
<span class="line"><span>    cluster = new control;</span></span>
<span class="line"><span>    cluster.p = pool2;</span></span>
<span class="line"><span>} {}</span></span></code></pre></div><p>Assignments elsewhere in the model will temporarily overwrite the value of one variable with the current state of the another.</p><h2 id="assertions-and-assumptions" tabindex="-1">Assertions and Assumptions <a class="header-anchor" href="#assertions-and-assumptions" aria-label="Permalink to &quot;Assertions and Assumptions&quot;">​</a></h2><p>You can constrain stock values using <code>assert</code> and <code>assume</code>. Both take an invariant expression and an optional temporal qualifier.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert pool.instances &gt; 0;</span></span>
<span class="line"><span>assume resources.blocks &gt;= 0;</span></span></code></pre></div><p><strong>Temporal qualifiers:</strong></p><table tabindex="0"><thead><tr><th>Qualifier</th><th>Meaning</th></tr></thead><tbody><tr><td><code>always</code></td><td>Must hold in every step</td></tr><tr><td><code>eventually</code></td><td>Must hold in at least one step</td></tr><tr><td><code>eventually-always</code></td><td>Must eventually hold and continue to hold</td></tr><tr><td><code>nmt &lt;n&gt;</code></td><td>Must hold no more than <code>n</code> times</td></tr><tr><td><code>nft &lt;n&gt;</code></td><td>Must hold no fewer than <code>n</code> times</td></tr></tbody></table><p><code>assert</code> tells the solver to find a counterexample. <code>assume</code> restricts the solution space — the solver will only explore scenarios where the assumption holds.</p><h2 id="concurrent-flows" tabindex="-1">Concurrent Flows <a class="header-anchor" href="#concurrent-flows" aria-label="Permalink to &quot;Concurrent Flows&quot;">​</a></h2><p>When calling a flow from the state chart or from the run block it is possible to tell Fault the these functions are running concurrently using a pipe <code>|</code> operator. You can see an example of this in <code>cache.fspec</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run init{</span></span>
<span class="line"><span>    r = new record;</span></span>
<span class="line"><span>} {</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>    r.store | r.release;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Here&#39;s what Fault does in this case: it generates two sets of rules, one where store runs and then release runs and another where release runs and then store runs. It then generates an or statement that asks the model checker to pick between those scenarios.</p><p>If there are more than two flows being called it will generate a set of rules for every possible combinations of orders the flows could happen in.</p><p>This allows Fault to check for race conditions.</p><h2 id="declarative-functions-unfunc" tabindex="-1">Declarative Functions: <code>unfunc</code> <a class="header-anchor" href="#declarative-functions-unfunc" aria-label="Permalink to &quot;Declarative Functions: \`unfunc\`&quot;">​</a></h2><p><code>unfunc</code> is a declarative alternative to <code>func</code>. Instead of imperative steps, you declare what a function <em>requires</em> (precondition) and what it <em>emits</em> (effects).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def ops = flow{</span></span>
<span class="line"><span>    st: new state,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    activate: unfunc{</span></span>
<span class="line"><span>        emits st.active = true,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    process: unfunc{</span></span>
<span class="line"><span>        requires st.active,</span></span>
<span class="line"><span>        emits st.processed = true,</span></span>
<span class="line"><span>        emits st.active = false,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>requires</code> — the condition that must hold for the function to be selected. The solver will only choose this function when the precondition is satisfiable.</p><p><code>emits</code> — declares an effect on a stock field. Multiple <code>emits</code> clauses are allowed. Supports all assignment forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Meaning</th></tr></thead><tbody><tr><td><code>emits st.x = val</code></td><td>Set field to value</td></tr><tr><td><code>emits st.x &lt;- expr</code></td><td>Increment field</td></tr><tr><td><code>emits st.x -&gt; expr</code></td><td>Decrement field</td></tr></tbody></table><p><code>unfunc</code> is primarily used with <a href="./../model-types/program-synthesis.html">program synthesis</a> — the solver fills <code>__</code> slots by choosing among available <code>unfunc</code> definitions.</p><h3 id="available" tabindex="-1"><code>available</code> <a class="header-anchor" href="#available" aria-label="Permalink to &quot;\`available\`&quot;">​</a></h3><p>The <code>available</code> temporal qualifier asserts that a function&#39;s precondition is satisfiable from the initial state:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume process available;</span></span></code></pre></div><p>Use this when you want to guarantee the solver can actually select a function, not just that it exists.</p>`,37)])])}const f=a(o,[["render",l]]);export{u as __pageData,f as default};
